const LAST_INPUT_KEY: &str = "last-input";

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        // Record the input this call received under `last-input`.
        let recorded = subscriptions.urls.join("\n");
        crate::aap::caps::state_rw::put(LAST_INPUT_KEY, &recorded);

        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls.iter() {
            // A request outside the handle's allowlist traps at the boundary;
